func (c *Client) SaveURL(entryURL string) error {
	requestBody, err := json.Marshal(&saveURLPayload{
		Type: "link",
		URL:  entryURL,
	})
	if err != nil {
		return fmt.Errorf("karakeep: unable to encode request body: %v", err)
	}

	req, err := http.NewRequest(http.MethodPost, c.apiEndpoint, bytes.NewReader(requestBody))
	if err != nil {
		return fmt.Errorf("karakeep: unable to create request: %v", err)
	}

	req.Header.Set("Authorization", "Bearer "+c.apiToken)
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", "Miniflux/"+version.Version)

	resp, err := c.wrapped.Do(req)
	if err != nil {
		return fmt.Errorf("karakeep: unable to send request: %v", err)
	}
	defer resp.Body.Close()

	responseBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return fmt.Errorf("karakeep: failed to parse response: %s", err)
	}

	if resp.StatusCode != http.StatusCreated {
		var errResponse errorResponse
		if err := json.Unmarshal(responseBody, &errResponse); err != nil {
			return fmt.Errorf("karakeep: unable to parse error response: status=%d body=%s", resp.StatusCode, string(responseBody))
		}
		return fmt.Errorf("karakeep: failed to save URL: status=%d errorcode=%s %s", resp.StatusCode, errResponse.Code, errResponse.Error)
	}

	var response saveURLResponse
	if err := json.Unmarshal(responseBody, &response); err != nil {
		return fmt.Errorf("karakeep: unable to parse response: %v", err)
	}

	if response.ID == "" {
		return errors.New("karakeep: unable to get ID from response")
	}

	if err := c.attachTags(response.ID); err != nil {
		return fmt.Errorf("karakeep: unable to attach tags: %v", err)
	}

	return nil
}

class TouchHandler {
    constructor() {
        this.reset();
    }

    reset() {
        this.touch = {
            start: { x: -1, y: -1 },
            move: { x: -1, y: -1 },
            moved: false,
            time: 0,
            element: null
        };
    }

    calculateDistance() {
        if (this.touch.start.x >= -1 && this.touch.move.x >= -1) {
            const horizontalDistance = Math.abs(this.touch.move.x - this.touch.start.x);
            const verticalDistance = Math.abs(this.touch.move.y - this.touch.start.y);

            if (horizontalDistance > 30 && verticalDistance < 70 || this.touch.moved) {
                return this.touch.move.x - this.touch.start.x;
            }
        }

        return 0;
    }

    static findElement(element) {
        if (element.classList.contains("entry-swipe")) {
            return element;
        }

        return element.closest(".entry-swipe");
    }

    onItemTouchStart(event) {
        if (event.touches === undefined || event.touches.length !== 1) {
            return;
        }

        this.reset();
        this.touch.start.x = event.touches[0].clientX;
        this.touch.start.y = event.touches[0].clientY;
        this.touch.element = TouchHandler.findElement(event.touches[0].target);
        this.touch.element.style.transitionDuration = "0s";
    }

    onItemTouchMove(event) {
        if (event.touches === undefined || event.touches.length !== 1 || this.touch.element === null) {
            return;
        }

        this.touch.move.x = event.touches[0].clientX;
        this.touch.move.y = event.touches[0].clientY;

        const distance = this.calculateDistance();
        const absDistance = Math.abs(distance);

        if (absDistance > 0) {
            this.touch.moved = true;

            const tx = (absDistance > 75 ? Math.sqrt(absDistance - 75) + 75 : absDistance) * Math.sign(distance);

            this.touch.element.style.transform = `translateX(${tx}px)`;

            event.preventDefault();
        }
    }

    onItemTouchEnd(event) {
        if (event.touches === undefined) {
            return;
        }

        if (this.touch.element !== null) {
            if (Math.abs(this.calculateDistance()) > 75) {
                toggleEntryStatus(this.touch.element);
            }

            if (this.touch.moved) {
                this.touch.element.style.transitionDuration = "0.15s";
                this.touch.element.style.transform = "none";
            }
        }

        this.reset();
    }

    onContentTouchStart(event) {
        if (event.touches === undefined || event.touches.length !== 1) {
            return;
        }

        this.reset();
        this.touch.start.x = event.touches[0].clientX;
        this.touch.start.y = event.touches[0].clientY;
        this.touch.time = Date.now();
    }

    onContentTouchMove(event) {
        if (event.touches === undefined || event.touches.length !== 1 || this.element === null) {
            return;
        }

        this.touch.move.x = event.touches[0].clientX;
        this.touch.move.y = event.touches[0].clientY;
    }

    onContentTouchEnd(event) {
        if (event.touches === undefined) {
            return;
        }

        if (Date.now() - this.touch.time <= 1000) {
            const distance = this.calculateDistance();
            const absDistance = Math.abs(distance);
            if (absDistance > 75) {
                if (distance > 0) {
                    goToPage("previous");

type Provider interface {
	// Config returns the OAuth2 configuration for this provider.
	Config() *oauth2.Config

	// UserExtraKey returns the key used to store the provider-specific user ID.
	UserExtraKey() string

	// Profile exchanges the authorization code for a token and fetches the user's profile.
	Profile(ctx context.Context, code, codeVerifier string) (*UserProfile, error)

	// PopulateUserCreationWithProfileID sets the provider-specific ID on a new user creation request.
	PopulateUserCreationWithProfileID(user *model.UserCreationRequest, profile *UserProfile)

	// PopulateUserWithProfileID sets the provider-specific ID on an existing user.
	PopulateUserWithProfileID(user *model.User, profile *UserProfile)

	// UserProfileID returns the provider-specific ID from the given user.
	UserProfileID(user *model.User) string

	// UnsetUserProfileID removes the provider-specific ID from the given user.
	UnsetUserProfileID(user *model.User)
}

func TestParseFeedWithoutLanguage(t *testing.T) {
	data := `<?xml version="1.0" encoding="utf-8"?>
	<feed xmlns="http://www.w3.org/2005/Atom">
		<title>Example Feed</title>
		<link href="http://example.org/"/>
		<updated>2003-12-13T18:30:02Z</updated>
		<id>urn:uuid:60a76c80-d399-11d9-b93C-0003939e0af6</id>
	</feed>`

	feed, err := Parse("http://example.org/feed.xml", bytes.NewReader([]byte(data)), "10")
	if err != nil {
		t.Fatal(err)
	}

	if feed.Language != "" {
		t.Errorf("Expected empty language, got: %q", feed.Language)
	}
}

