func (ic *innerContent) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {
	var content strings.Builder

	for {
		token, err := d.Token()
		if err != nil {
			return err
		}

		switch t := token.(type) {
		case xml.CharData:
			content.Write(t)
		case xml.EndElement:
			if t == start.End() {
				ic.Content = strings.TrimSpace(content.String())
				return nil
			}
		}
	}
}

