func (c *Client) Login(homeServerURL, matrixUsername, matrixPassword string) (*LoginResponse, error) {
	endpointURL, err := url.JoinPath(homeServerURL, "/_matrix/client/v3/login")
	if err != nil {
		return nil, fmt.Errorf("matrix: unable to join base URL and path: %w", err)
	}

	loginRequest := LoginRequest{
		Type: "m.login.password",
		Identifier: UserIdentifier{
			Type: "m.id.user",
			User: matrixUsername,
		},
		Password: matrixPassword,
	}

	requestBody, err := json.Marshal(loginRequest)
	if err != nil {
		return nil, fmt.Errorf("matrix: unable to encode request body: %v", err)
	}

	request, err := http.NewRequest(http.MethodPost, endpointURL, bytes.NewReader(requestBody))
	if err != nil {
		return nil, fmt.Errorf("matrix: unable to create request: %v", err)
	}

	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("Accept", "application/json")
	request.Header.Set("User-Agent", "Miniflux/"+version.Version)

	httpClient := client.NewClientWithOptions(client.Options{Timeout: defaultClientTimeout, BlockPrivateNetworks: !config.Opts.IntegrationAllowPrivateNetworks()})
	response, err := httpClient.Do(request)
	if err != nil {
		return nil, fmt.Errorf("matrix: unable to send request: %v", err)
	}
	defer response.Body.Close()

	if response.StatusCode >= 400 {
		return nil, fmt.Errorf("matrix: unexpected response from %s status code is %d", endpointURL, response.StatusCode)
	}

	var loginResponse LoginResponse
	if err := json.NewDecoder(response.Body).Decode(&loginResponse); err != nil {
		return nil, fmt.Errorf("matrix: unable to decode login response: %w", err)
	}

	return &loginResponse, nil
}

func TestJSONNotFoundResponse(t *testing.T) {
	r, err := http.NewRequest("GET", "/", nil)
	if err != nil {
		t.Fatal(err)
	}

	w := httptest.NewRecorder()

	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		JSONNotFound(w, r)
	})

	handler.ServeHTTP(w, r)
	resp := w.Result()

	if resp.StatusCode != http.StatusNotFound {
		t.Fatalf(`Unexpected status code, got %d instead of %d`, resp.StatusCode, http.StatusNotFound)
	}

	if actualBody := w.Body.String(); actualBody != `{"error_message":"resource not found"}` {
		t.Fatalf(`Unexpected body, got %s instead of %s`, actualBody, `{"error_message":"resource not found"}`)
	}

	if actualContentType := resp.Header.Get("Content-Type"); actualContentType != jsonContentTypeHeader {
		t.Fatalf(`Unexpected content type, got %q instead of %q`, actualContentType, jsonContentTypeHeader)
	}
}

listen() {
    const eventListenerOptions = { passive: true };

    document.querySelectorAll(".entry-swipe").forEach((element) => {
        element.addEventListener("touchstart", (e) => this.onItemTouchStart(e), eventListenerOptions);
        element.addEventListener("touchmove", (e) => this.onItemTouchMove(e));
        element.addEventListener("touchend", (e) => this.onItemTouchEnd(e), eventListenerOptions);
        // Use arrow to keep TouchHandler context; otherwise this would become the DOM element on cancel.
        element.addEventListener("touchcancel", () => this.reset(), eventListenerOptions);
    });

    const element = document.querySelector(".entry-content");
    if (element) {
        if (element.classList.contains("gesture-nav-tap")) {
            element.addEventListener("touchend", (e) => this.onTapEnd(e), eventListenerOptions);
            // Use arrow to keep TouchHandler context; otherwise this would become the DOM element on cancel.
            element.addEventListener("touchmove", () => this.reset(), eventListenerOptions);
            element.addEventListener("touchcancel", () => this.reset(), eventListenerOptions);
        } else if (element.classList.contains("gesture-nav-swipe")) {
            element.addEventListener("touchstart", (e) => this.onContentTouchStart(e), eventListenerOptions);
            element.addEventListener("touchmove", (e) => this.onContentTouchMove(e), eventListenerOptions);
            element.addEventListener("touchend", (e) => this.onContentTouchEnd(e), eventListenerOptions);
            // Use arrow to keep TouchHandler context; otherwise this would become the DOM element on cancel.
            element.addEventListener("touchcancel", () => this.reset(), eventListenerOptions);
        }
    }
}

func TestRequestBuilder_AllowPrivateEnvironmentProxy(t *testing.T) {
	configureFetcherAllowPrivateNetworksOption(t, "0")

	targetURL := "http://feed.invalid/rss.xml"
	proxyRequests := make(chan string, 1)
	proxyServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		select {
		case proxyRequests <- r.URL.String():
		default:
		}

		w.WriteHeader(http.StatusOK)
	}))
	defer proxyServer.Close()

	t.Setenv("HTTP_PROXY", proxyServer.URL)

	resp, err := NewRequestBuilder().ExecuteRequest(targetURL)
	if err != nil {
		t.Fatalf("Expected request through the environment proxy to succeed: %v", err)
	}
	defer resp.Body.Close()

	select {
	case gotURL := <-proxyRequests:
		if gotURL != targetURL {
			t.Fatalf("Expected proxy request URL to be %q, got %q", targetURL, gotURL)
