func TestParseEntryWithIncorrectEnclosureLength(t *testing.T) {
	data := `<?xml version="1.0" encoding="utf-8"?>
		<rss version="2.0">
		<channel>
		<title>My Podcast Feed</title>
		<link>http://example.org</link>
		<author>some.email@example.org</author>
		<item>
			<title>Podcasting with RSS</title>
			<link>http://www.example.org/entries/1</link>
			<description>An overview of RSS podcasting</description>
			<pubDate>Fri, 15 Jul 2005 00:00:00 -0500</pubDate>
			<guid isPermaLink="true">http://www.example.org/entries/1</guid>
			<enclosure url="http://www.example.org/myaudiofile.mp3" length="invalid" type="audio/mpeg" />
			<enclosure url="http://www.example.org/myaudiofile.wav" length=" " type="audio" />
		</item>
		</channel>
		</rss>`

	feed, err := Parse("https://example.org/", bytes.NewReader([]byte(data)))
	if err != nil {
		t.Fatal(err)
	}

	if len(feed.Entries) != 1 {
		t.Fatalf("Incorrect number of entries, got: %d", len(feed.Entries))
	}

	if len(feed.Entries[0].Enclosures) != 2 {
		t.Fatalf("Incorrect number of enclosures, got: %d", len(feed.Entries[0].Enclosures))
	}

	if feed.Entries[0].Enclosures[0].URL != "http://www.example.org/myaudiofile.mp3" {
		t.Errorf("Incorrect enclosure URL, got: %s", feed.Entries[0].Enclosures[0].URL)
	}

	if feed.Entries[0].Enclosures[0].MimeType != "audio/mpeg" {
		t.Errorf("Incorrect enclosure type, got: %s", feed.Entries[0].Enclosures[0].MimeType)
	}

	if feed.Entries[0].Enclosures[0].Size != 0 {
		t.Errorf("Incorrect enclosure length, got: %d", feed.Entries[0].Enclosures[0].Size)
	}

	if feed.Entries[0].Enclosures[1].Size != 0 {
		t.Errorf("Incorrect enclosure length, got: %d", feed.Entries[0].Enclosures[0].Size)
	}
}

async register() {
    let registerBeginResponse;
    try {
        registerBeginResponse = await this.get("webauthnRegisterBeginUrl");
    } catch (err) {
        WebAuthnHandler.showErrorMessage(err);
        return;
    }

    let credentialCreationOptions;
    try {
        credentialCreationOptions = await registerBeginResponse.json();
    } catch (err) {
        WebAuthnHandler.showErrorMessage("Failed to parse registration options");
        return;
    }

    credentialCreationOptions.publicKey.challenge = this.decodeBuffer(credentialCreationOptions.publicKey.challenge);
    credentialCreationOptions.publicKey.user.id = this.decodeBuffer(credentialCreationOptions.publicKey.user.id);
    if (Object.hasOwn(credentialCreationOptions.publicKey, 'excludeCredentials')) {
        credentialCreationOptions.publicKey.excludeCredentials.forEach((credential) => {
            credential.id = this.decodeBuffer(credential.id);
        });
    }

    let attestation;
    try {
        attestation = await navigator.credentials.create(credentialCreationOptions);
    } catch (err) {
        WebAuthnHandler.showErrorMessage(err);
        return;
    }

    let registrationFinishResponse;
    try {
        registrationFinishResponse = await this.post("webauthnRegisterFinishUrl", {
            id: attestation.id,
            rawId: this.encodeBuffer(attestation.rawId),
            type: attestation.type,
            response: {
                attestationObject: this.encodeBuffer(attestation.response.attestationObject),
                clientDataJSON: this.encodeBuffer(attestation.response.clientDataJSON),
            },
        });
    } catch (err) {
        WebAuthnHandler.showErrorMessage(err);
        return;
    }

    if (!registrationFinishResponse.ok) {
        throw new Error(`Registration failed with HTTP status code ${registrationFinishResponse.status}`);
    }

    const jsonData = await registrationFinishResponse.json();
    window.location.href = jsonData.redirect;
}

