// RemoveAndReplaceCategoriesByName deletes categories with the given titles and
// reassigns affected feeds to the user's first remaining category. It returns
// an error if the deletion would leave the user without any categories.

source:
func (s *Storage) RemoveAndReplaceCategoriesByName(userid int64, titles []string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return errors.New("store: unable to begin transaction")
	}

	titleParam := pq.Array(titles)
	var count int
	query := "SELECT count(*) FROM categories WHERE user_id = $1 AND title <> ALL($2)"
	err = tx.QueryRow(query, userid, titleParam).Scan(&count)
	if err != nil {
		tx.Rollback()
		return errors.New("store: unable to retrieve category count")
	}
	if count < 1 {
		tx.Rollback()
		return errors.New("store: at least 1 category must remain after deletion")
	}

	query = `
		WITH d_cats AS (SELECT id FROM categories WHERE user_id = $1 AND title = ANY($2))
		UPDATE feeds
		 SET category_id =
		  (SELECT id
			FROM categories
			WHERE user_id = $1 AND id NOT IN (SELECT id FROM d_cats)
			ORDER BY title ASC
			LIMIT 1)
		WHERE user_id = $1 AND category_id IN (SELECT id FROM d_cats)
	`
	_, err = tx.Exec(query, userid, titleParam)
	if err != nil {
		tx.Rollback()
		return fmt.Errorf("store: unable to replace categories: %v", err)
	}

	query = "DELETE FROM categories WHERE user_id = $1 AND title = ANY($2)"
	_, err = tx.Exec(query, userid, titleParam)
	if err != nil {
		tx.Rollback()
		return fmt.Errorf("store: unable to delete categories: %v", err)
	}
	tx.Commit()
	return nil
}

func TestIsDateMatchingPatternEdgeCases(t *testing.T) {
	testDate := time.Date(2023, 6, 15, 12, 0, 0, 0, time.UTC)

	// Test edge case: between with boundary dates
	result := isDateMatchingPattern("between:2023-06-15,2023-06-15", testDate)
	if result {
		t.Errorf("isDateMatchingPattern() should return false for date exactly on boundaries")
	}

	// Test edge case: max-age with hours
	now := time.Now()
	oldEntry := now.Add(-25 * time.Hour)
	result = isDateMatchingPattern("max-age:24h", oldEntry)
	if !result {
		t.Errorf("isDateMatchingPattern() should match old entry with max-age in hours")
	}
}

func (e *EntryQueryBuilder) BeforeEntryID(entryID int64) *EntryQueryBuilder {
	if entryID != 0 {
		e.conditions = append(e.conditions, "e.id < $"+strconv.Itoa(len(e.args)+1))
		e.args = append(e.args, entryID)
	}
	return e
}

func TestHasFormattingDirective(t *testing.T) {
	tests := map[string]bool{
		"دقيقتين":   false,
		"%d دقيقة":  true,
		"90%% done": false, // escaped percent consumes no argument
		"%d of %s":  true,
		"":          false,
		"%":         true,
	}

	for format, expected := range tests {
		if got := hasFormattingDirective(format); got != expected {
			t.Errorf(`hasFormattingDirective(%q) = %v, want %v`, format, got, expected)
		}
	}
}

